import fs from 'fs-extra';
import path from 'path';
import chalk from 'chalk';
import { ProjectConfig } from './types.js';
import { generateSecret } from './utils.js';

export async function generateConfigYaml(
  projectPath: string,
  config: ProjectConfig
): Promise<void> {
  const configContent = `# Flix Yourself Configuration
# Generated by create-flix-yourself

database:
  provider: ${config.databaseProvider}

storage:
  provider: ${config.storageProvider}

auth:
  provider: ${config.authProvider}

content:
  preset: ${config.contentPreset}

features:
  continueWatching: true
  history: true
  profiles: ${config.authProvider !== 'none'}
  search: true
  subtitles: false
  recommendations: true
`;

  const configPath = path.join(projectPath, 'config.yaml');
  await fs.writeFile(configPath, configContent, 'utf-8');
  console.log(chalk.gray('  ✓ Created config.yaml'));
}

export async function generateEnvFile(
  projectPath: string,
  config: ProjectConfig
): Promise<void> {
  let envContent = '# Environment Configuration\n';
  envContent += '# Generated by create-flix-yourself\n\n';

  // Database configuration
  envContent += '# Database\n';
  envContent += `DATABASE_PROVIDER=${config.databaseProvider}\n`;

  switch (config.databaseProvider) {
    case 'sqlite':
      envContent += 'DATABASE_URL=file:./dev.db\n';
      break;
    case 'postgresql':
      envContent += '# Add your PostgreSQL connection URL below:\n';
      envContent += 'DATABASE_URL=postgresql://user:password@localhost:5432/flix_yourself\n';
      break;
    case 'cockroachdb':
      envContent += '# Add your CockroachDB connection URL below:\n';
      envContent += 'DATABASE_URL=postgresql://user:password@host:26257/defaultdb?sslmode=verify-full\n';
      break;
  }

  envContent += '\n# Storage\n';
  envContent += `STORAGE_PROVIDER=${config.storageProvider}\n`;

  switch (config.storageProvider) {
    case 'local':
      envContent += 'STORAGE_LOCAL_PATH=./uploads\n';
      break;
    case 's3':
      envContent += '# Add your AWS S3 credentials below:\n';
      envContent += 'AWS_ACCESS_KEY_ID=\n';
      envContent += 'AWS_SECRET_ACCESS_KEY=\n';
      envContent += 'AWS_REGION=us-east-1\n';
      envContent += 'AWS_S3_BUCKET=\n';
      break;
    case 'r2':
      envContent += '# Add your Cloudflare R2 credentials below:\n';
      envContent += 'R2_ACCOUNT_ID=\n';
      envContent += 'R2_ACCESS_KEY_ID=\n';
      envContent += 'R2_SECRET_ACCESS_KEY=\n';
      envContent += 'R2_BUCKET_NAME=\n';
      break;
    case 'gcs':
      envContent += '# Add your Google Cloud Storage credentials below:\n';
      envContent += 'GCS_PROJECT_ID=\n';
      envContent += 'GCS_BUCKET_NAME=\n';
      envContent += 'GCS_KEYFILE_PATH=./gcs-keyfile.json\n';
      break;
    case 'azure':
      envContent += '# Add your Azure Blob Storage credentials below:\n';
      envContent += 'AZURE_STORAGE_ACCOUNT_NAME=\n';
      envContent += 'AZURE_STORAGE_ACCESS_KEY=\n';
      envContent += 'AZURE_STORAGE_CONTAINER_NAME=\n';
      break;
  }

  // Authentication configuration
  envContent += '\n# Authentication\n';
  envContent += `AUTH_PROVIDER=${config.authProvider}\n`;

  if (config.authProvider === 'internal' || config.authProvider === 'nextauth') {
    const authSecret = generateSecret(32);
    envContent += `AUTH_SECRET=${authSecret}\n`;
  }

  if (config.authProvider === 'nextauth') {
    envContent += 'NEXTAUTH_URL=http://localhost:3000\n';
    const nextAuthSecret = generateSecret(32);
    envContent += `NEXTAUTH_SECRET=${nextAuthSecret}\n`;
    envContent += '\n# OAuth Provider Configuration (add your keys):\n';
    envContent += '# GOOGLE_CLIENT_ID=\n';
    envContent += '# GOOGLE_CLIENT_SECRET=\n';
    envContent += '# GITHUB_CLIENT_ID=\n';
    envContent += '# GITHUB_CLIENT_SECRET=\n';
  }

  // Application configuration
  envContent += '\n# Application\n';
  envContent += 'NODE_ENV=development\n';
  envContent += 'PORT=3000\n';

  const envPath = path.join(projectPath, '.env');
  await fs.writeFile(envPath, envContent, 'utf-8');
  console.log(chalk.gray('  ✓ Created .env'));
}

export async function patchPrismaSchema(
  projectPath: string,
  databaseProvider: string
): Promise<void> {
  const schemaPath = path.join(projectPath, 'prisma', 'schema.prisma');

  try {
    // Check if schema file exists
    if (!(await fs.pathExists(schemaPath))) {
      console.log(chalk.yellow('  ⚠ Prisma schema not found, skipping patch'));
      return;
    }

    let schemaContent = await fs.readFile(schemaPath, 'utf-8');

    // Update the datasource provider
    // Look for datasource db block and update provider
    const datasourceRegex = /datasource\s+db\s*{[^}]*provider\s*=\s*env\("DATABASE_PROVIDER"\)[^}]*}/s;
    
    if (datasourceRegex.test(schemaContent)) {
      // Keep env var approach - it's already correct
      console.log(chalk.gray('  ✓ Prisma schema already uses DATABASE_PROVIDER env var'));
    } else {
      // Fallback: try to find and replace provider line
      const providerRegex = /provider\s*=\s*"[^"]+"/;
      if (providerRegex.test(schemaContent)) {
        schemaContent = schemaContent.replace(
          providerRegex,
          `provider = env("DATABASE_PROVIDER")`
        );
        await fs.writeFile(schemaPath, schemaContent, 'utf-8');
        console.log(chalk.gray('  ✓ Updated Prisma schema provider'));
      }
    }
  } catch (error) {
    console.log(chalk.yellow('  ⚠ Could not patch Prisma schema:', (error as Error).message));
  }
}
